-- lahja 0.1.0
-- Generated by scripts/build-package.mjs from db/. Do not edit by hand.

-- ===== 001_normalize.sql =====

-- 001_normalize.sql
-- lahja.normalize(text): folds the many ways Arabic is written into one search form.
-- Apply in the Supabase SQL editor. Safe to run again.
-- After changing this function, re-run 900 and 901: stored search columns do not
-- recompute when the function changes.

create schema if not exists lahja;

create or replace function lahja.normalize(input text)
returns text
language sql
immutable
strict
parallel safe
as $$
  select btrim(
    regexp_replace(
      lower(
        translate(
          -- 1. remove diacritics (U+064B to U+0652), superscript alef (U+0670),
          --    tatweel (U+0640) and invisible direction and joiner marks
          regexp_replace(input, '[\u064B-\u0652\u0670\u0640\u200C-\u200F]', '', 'g'),
          -- 2. fold letter variants and digits
          --    أ إ آ ٱ -> ا   ى -> ي   ة -> ه   ؤ -> و   ئ -> ي   Persian ک ی -> ك ي
          --    Arabic-Indic and Persian digits -> 0 to 9
          'أإآٱىةؤئکی٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹',
          'اااايهويكي01234567890123456789'
        )
      ),
      -- 3. collapse all whitespace into single spaces
      '\s+', ' ', 'g'
    )
  )
$$;

comment on function lahja.normalize(text) is
  'Folds Arabic spelling variants, diacritics and digits into one form for search.';

-- ===== 003_skeleton.sql =====

-- 003_skeleton.sql
-- Consonant skeletons: Arabic and Arabizi words reduced to the consonants they share.
--   3asal -> عسل      عسل -> عسل
--   zeit zeitoon -> زت زتن      زيت زيتون -> زت زتن
-- Vowels (a e i o u, ا و ي) are dropped because Arabizi spells them inconsistently.
-- Letters that Arabizi writers do not tell apart are merged:
--   ص->س  ض->د  ط->ت  ظ ذ->ز  ث->ت  ق->ك  ح->ه
-- Requires 001_normalize.sql. Safe to run again.
-- After changing these functions, re-run 900 and 901.

create or replace function lahja.skeleton_word(word text)
returns text
language plpgsql
immutable
strict
parallel safe
as $$
declare
  w text := word;
begin
  if w ~ '[a-z]' then
    -- Arabizi word
    if w in ('al', 'el', 'il') then
      return '';
    end if;
    w := regexp_replace(w, '^(al|el|il)-', '');
    w := replace(w, 'sh', 'ش');
    w := replace(w, 'ch', 'ش');
    w := replace(w, 'kh', 'خ');
    w := replace(w, 'gh', 'غ');
    w := replace(w, 'th', 'ت');
    w := replace(w, 'dh', 'ز');
    -- b p t j g d r z s f v q k c x l m n h 3 7 5 6 9
    w := translate(w, 'bptjgdrzsfvqkcxlmnh37569', 'ببتججدرزسففككككلمنهعهختك');
    -- drop vowels, 2, 8 and anything else that is not an Arabic letter
    w := regexp_replace(w, '[^ء-ي]', '', 'g');
  elsif w ~ '[ء-ي]' then
    -- Arabic word (already normalised): drop the article when 2+ letters follow
    w := regexp_replace(w, '^ال(?=..)', '');
    w := translate(w, 'صضطظذثقح', 'سدتززتكه');
    w := regexp_replace(w, '[^ء-ي0-9]', '', 'g');
  else
    -- numbers and other tokens stay as they are
    return w;
  end if;

  w := translate(w, 'اويءى', '');               -- drop long vowels and hamza
  w := regexp_replace(w, '(.)\1+', '\1', 'g');  -- collapse doubled letters
  if length(w) >= 3 then
    w := regexp_replace(w, 'ه$', '');           -- drop final ه (taa marbuta after normalize)
  end if;
  return w;
end
$$;

-- Skeleton of a whole text. Words that shrink below 2 letters are dropped,
-- because one-letter skeletons match too much.
create or replace function lahja.skeleton(input text)
returns text
language sql
immutable
strict
parallel safe
as $$
  select coalesce(string_agg(s, ' ' order by n), '')
  from (
    select n, lahja.skeleton_word(w) as s
    from regexp_split_to_table(lahja.normalize(input), ' ') with ordinality as t(w, n)
  ) words
  where length(s) >= 2
$$;

comment on function lahja.skeleton(text) is
  'Consonant skeleton of Arabic or Arabizi text, for matching across scripts and spellings.';

-- ===== 005_lexicon.sql =====

-- 005_lexicon.sql
-- Dialect synonyms and filler words, and the functions that use them at query time.
--   lahja.lexicon: one row per (word, group). Words in the same group are synonyms.
--                  kind 'filler' marks words that carry no product meaning (بدي, عايز, منيح).
--   lahja.strip_fillers(text): removes filler words from a query.
--   lahja.dialect_query(text): builds a tsquery where each word also matches its synonyms.
-- Words are stored normalised. Users can add their own rows.
-- Requires 001_normalize.sql. Safe to run again: starter rows are re-inserted or re-marked
-- without duplicates and user rows are kept.

create table if not exists lahja.lexicon (
  word text not null,
  grp  text not null,
  kind text not null default 'synonym' check (kind in ('synonym', 'filler')),
  primary key (word, grp)
);

create index if not exists lexicon_word_idx on lahja.lexicon (word);

-- Starter rows come from this file; user rows do not. As an extension, only user rows
-- are included in backups, so a restore does not insert starter rows twice.
alter table lahja.lexicon add column if not exists is_starter boolean not null default false;

-- Starter data: general Arabic dialect vocabulary across product types, not tuned to any test set.
-- Ambiguous words are left out on purpose: براد (fridge in the Levant, teapot in Morocco),
-- لبن (milk in Egypt, yogurt in the Levant).
insert into lahja.lexicon (word, grp, kind, is_starter)
select lahja.normalize(word), grp, kind, true
from (values
  -- footwear
  ('حذاء', 'shoes', 'synonym'), ('كندرة', 'shoes', 'synonym'), ('جزمة', 'shoes', 'synonym'),
  ('صباط', 'shoes', 'synonym'), ('بوط', 'shoes', 'synonym'), ('بوت', 'shoes', 'synonym'),
  ('شبشب', 'slippers', 'synonym'), ('شحاطة', 'slippers', 'synonym'), ('زنوبة', 'slippers', 'synonym'),
  -- clothing
  ('بنطلون', 'trousers', 'synonym'), ('بنطال', 'trousers', 'synonym'), ('سروال', 'trousers', 'synonym'),
  ('جاكيت', 'jacket', 'synonym'), ('جاكيتة', 'jacket', 'synonym'), ('معطف', 'jacket', 'synonym'),
  ('قميص', 'shirt', 'synonym'), ('شميز', 'shirt', 'synonym'),
  ('حجاب', 'hijab', 'synonym'), ('طرحة', 'hijab', 'synonym'),
  ('شنطة', 'bag', 'synonym'), ('حقيبة', 'bag', 'synonym'), ('جنطة', 'bag', 'synonym'),
  -- phones and computers
  ('جوال', 'phone', 'synonym'), ('موبايل', 'phone', 'synonym'), ('هاتف', 'phone', 'synonym'),
  -- محمول is left out: it also means laptop in حاسوب محمول
  ('تلفون', 'phone', 'synonym'), ('تليفون', 'phone', 'synonym'),
  ('كفر', 'phone_case', 'synonym'), ('جراب', 'phone_case', 'synonym'),
  ('لابتوب', 'laptop', 'synonym'), ('حاسوب محمول', 'laptop', 'synonym'), ('كمبيوتر محمول', 'laptop', 'synonym'),
  ('كمبيوتر', 'computer', 'synonym'), ('حاسوب', 'computer', 'synonym'), ('حاسب', 'computer', 'synonym'),
  ('ماوس', 'mouse', 'synonym'), ('فأرة', 'mouse', 'synonym'),
  ('كيبورد', 'keyboard', 'synonym'), ('لوحة مفاتيح', 'keyboard', 'synonym'),
  ('سماعات', 'headphones', 'synonym'), ('هيدفون', 'headphones', 'synonym'), ('سماعة', 'headphones', 'synonym'),
  ('باور بانك', 'power_bank', 'synonym'), ('بطارية متنقلة', 'power_bank', 'synonym'), ('شاحن متنقل', 'power_bank', 'synonym'),
  ('تلفزيون', 'tv', 'synonym'), ('تلفاز', 'tv', 'synonym'),
  -- home and kitchen
  ('غلاية', 'kettle', 'synonym'), ('كتلي', 'kettle', 'synonym'), ('كاتل', 'kettle', 'synonym'),
  ('ثلاجة', 'fridge', 'synonym'), ('تلاجة', 'fridge', 'synonym'),
  ('طنجرة', 'pot', 'synonym'), ('حلة', 'pot', 'synonym'), ('قدر', 'pot', 'synonym'),
  ('مقلاة', 'pan', 'synonym'), ('طاوة', 'pan', 'synonym'), ('مقلاية', 'pan', 'synonym'),
  ('كوب', 'cup', 'synonym'), ('كاسة', 'cup', 'synonym'), ('كباية', 'cup', 'synonym'),
  ('فنجان', 'coffee_cup', 'synonym'), ('فنجال', 'coffee_cup', 'synonym'),
  ('مكيف', 'air_conditioner', 'synonym'), ('كونديشن', 'air_conditioner', 'synonym'), ('تكييف', 'air_conditioner', 'synonym'),
  ('بطانية', 'blanket', 'synonym'), ('حرام', 'blanket', 'synonym'), ('لحاف', 'blanket', 'synonym'),
  ('مخدة', 'pillow', 'synonym'), ('وسادة', 'pillow', 'synonym'),
  -- food and drink (Arabizi spellings included where common)
  ('قهوة', 'coffee', 'synonym'), ('ahwe', 'coffee', 'synonym'), ('ahweh', 'coffee', 'synonym'),
  ('2ahwe', 'coffee', 'synonym'), ('gahwa', 'coffee', 'synonym'), ('qahwa', 'coffee', 'synonym'),
  ('شاي', 'tea', 'synonym'), ('shay', 'tea', 'synonym'), ('chai', 'tea', 'synonym'),
  ('ماء', 'water', 'synonym'), ('مي', 'water', 'synonym'), ('مية', 'water', 'synonym'), ('مويه', 'water', 'synonym'),
  ('خبز', 'bread', 'synonym'), ('عيش', 'bread', 'synonym'),
  ('طماطم', 'tomato', 'synonym'), ('بندورة', 'tomato', 'synonym'), ('قوطة', 'tomato', 'synonym'),
  ('بطاطس', 'potato', 'synonym'), ('بطاطا', 'potato', 'synonym'),
  -- filler: wanting, asking, and vague quality words
  ('بدي', 'want', 'filler'), ('بدنا', 'want', 'filler'), ('بدك', 'want', 'filler'),
  ('عايز', 'want', 'filler'), ('عاوز', 'want', 'filler'), ('عايزة', 'want', 'filler'),
  ('ابغى', 'want', 'filler'), ('ابي', 'want', 'filler'), ('ودي', 'want', 'filler'),
  ('اريد', 'want', 'filler'), ('نريد', 'want', 'filler'), ('حابب', 'want', 'filler'),
  ('محتاج', 'want', 'filler'), ('ابحث', 'want', 'filler'), ('عن', 'want', 'filler'),
  ('منيح', 'quality', 'filler'), ('منيحة', 'quality', 'filler'), ('كويس', 'quality', 'filler'),
  ('كويسة', 'quality', 'filler'), ('زين', 'quality', 'filler'), ('حلو', 'quality', 'filler'),
  ('حلوة', 'quality', 'filler'), ('ممتاز', 'quality', 'filler'), ('رخيص', 'quality', 'filler')
) as starter(word, grp, kind)
-- rows from older versions of this file are marked as starter rows too
on conflict (word, grp) do update set is_starter = true;

-- Removes filler words. Stable, not immutable: it reads lahja.lexicon.
create or replace function lahja.strip_fillers(input text)
returns text
language sql
stable
strict
parallel safe
as $$
  select coalesce(string_agg(w, ' ' order by n), '')
  from regexp_split_to_table(lahja.normalize(input), ' ') with ordinality as t(w, n)
  where not exists (
    select 1 from lahja.lexicon l where l.word = t.w and l.kind = 'filler'
  )
$$;

-- Each remaining word matches itself OR any word in its synonym groups; words are ANDed.
-- Two-word lexicon entries (باور بانك) are matched first, as one unit.
-- Uses the 'arabic' config, so it pairs with columns built as
-- to_tsvector('arabic', lahja.normalize(...)).
create or replace function lahja.dialect_query(input text)
returns tsquery
language plpgsql
stable
strict
parallel safe
as $$
declare
  words  text[] := array_remove(string_to_array(lahja.strip_fillers(input), ' '), '');
  i      int := 1;
  unit   text;
  syn    text;
  part   tsquery;
  result tsquery := ''::tsquery;
begin
  while i <= coalesce(array_length(words, 1), 0) loop
    unit := words[i];
    if i < array_length(words, 1)
       and exists (select 1 from lahja.lexicon where word = words[i] || ' ' || words[i + 1]) then
      unit := words[i] || ' ' || words[i + 1];
      i := i + 1;
    end if;
    i := i + 1;

    part := plainto_tsquery('arabic', unit);
    for syn in
      select distinct other.word
      from lahja.lexicon mine
      join lahja.lexicon other on other.grp = mine.grp and other.kind = 'synonym'
      where mine.word = unit and mine.kind = 'synonym' and other.word <> unit
    loop
      part := part || plainto_tsquery('arabic', syn);
    end loop;
    result := result && part;
  end loop;
  return result;
end
$$;

comment on function lahja.dialect_query(text) is
  'Query with filler words removed and each word expanded to its dialect synonyms.';

-- ===== 007_search.sql =====

-- 007_search.sql
-- The public search API: one column, one query function, one rank function.
--
--   alter table products add column search tsvector
--     generated always as (lahja.to_document(title || ' ' || description)) stored;
--   create index on products using gin (search);
--
--   select p.*
--   from products p, lahja.to_query('بدي 3asal sidr') q
--   where p.search @@ q
--   order by lahja.rank(p.search, q) desc;
--
-- Every word is stored in three layers, each with a tsvector weight:
--   A  exact:    lahja.normalize(), no stemming          (strongest)
--   B  stemmed:  Postgres 'arabic' stemmer on normalised text
--   C  skeleton: lahja.skeleton() of Arabic-script words  (weakest)
-- Each query word may match through any layer, or through a lexicon synonym (B).
-- Query words are ANDed, so all of them must match some layer.
-- Requires 001, 003 and 005. Safe to run again.
-- After changing these functions, re-run 900 and 901.

-- Adds a weight to every lexeme of a tsquery: 'عسل' & 'سدر' -> 'عسل':A & 'سدر':A
create or replace function lahja.weighted(query tsquery, weight text)
returns tsquery
language sql
immutable
strict
parallel safe
as $$
  select case
    when query::text = '' then query
    else regexp_replace(query::text, '(''(?:[^'']|'''')*'')', '\1:' || weight, 'g')::tsquery
  end
$$;

create or replace function lahja.to_document(input text)
returns tsvector
language sql
immutable
strict
parallel safe
as $$
  select setweight(to_tsvector('simple'::regconfig, lahja.normalize(input)), 'A')
      || setweight(to_tsvector('arabic'::regconfig, lahja.normalize(input)), 'B')
      -- Latin words are left out of the skeleton layer: English product words
      -- would only add noise against Arabizi queries
      || setweight(to_tsvector('simple'::regconfig,
           lahja.skeleton(regexp_replace(lahja.normalize(input), '\S*[a-z]\S*', ' ', 'g'))), 'C')
$$;

create or replace function lahja.to_query(input text)
returns tsquery
language plpgsql
stable
strict
parallel safe
as $$
declare
  words  text[] := array_remove(string_to_array(lahja.strip_fillers(input), ' '), '');
  i      int := 1;
  unit   text;
  syn    text;
  part   tsquery;
  result tsquery := ''::tsquery;
begin
  while i <= coalesce(array_length(words, 1), 0) loop
    unit := words[i];
    -- two-word lexicon entries (باور بانك) are one unit
    if i < array_length(words, 1)
       and exists (select 1 from lahja.lexicon where word = words[i] || ' ' || words[i + 1]) then
      unit := words[i] || ' ' || words[i + 1];
      i := i + 1;
    end if;
    i := i + 1;

    part := lahja.weighted(plainto_tsquery('simple', unit), 'A')
         || lahja.weighted(plainto_tsquery('arabic', unit), 'B')
         || lahja.weighted(plainto_tsquery('simple', lahja.skeleton(unit)), 'C');
    for syn in
      select distinct other.word
      from lahja.lexicon mine
      join lahja.lexicon other on other.grp = mine.grp and other.kind = 'synonym'
      where mine.word = unit and mine.kind = 'synonym' and other.word <> unit
    loop
      part := part || lahja.weighted(plainto_tsquery('arabic', syn), 'B');
    end loop;
    result := result && part;
  end loop;
  return result;
end
$$;

-- Weights for D, C, B, A: exact matches count most, skeleton matches least.
create or replace function lahja.rank(document tsvector, query tsquery)
returns real
language sql
immutable
strict
parallel safe
as $$
  select ts_rank('{0.0, 0.1, 0.4, 1.0}'::real[], document, query)
$$;

comment on function lahja.to_document(text) is
  'Search document for a generated column: exact (A), stemmed (B) and skeleton (C) layers.';
comment on function lahja.to_query(text) is
  'Search query: fillers removed, each word matches exact, stemmed, skeleton or a lexicon synonym.';
comment on function lahja.rank(tsvector, tsquery) is
  'Relevance score: exact matches rank above stemmed, stemmed above skeleton.';

-- ===== 009_hybrid.sql =====

-- 009_hybrid.sql
-- Hybrid search: merge keyword results (lahja.to_query) with vector results (pgvector)
-- using Reciprocal Rank Fusion (RRF). Keyword search finds exact words, spellings and
-- Arabizi; vector search finds products with the same meaning but different words
-- (جلابية -> ثوب). RRF only looks at the rank in each list, so the two scores never
-- need to be on the same scale.
--
-- This file does not need pgvector. Your table needs it for the embedding column:
--
--   create extension if not exists vector with schema extensions;
--   alter table products add column embedding extensions.vector(384);
--   -- fill embedding with any multilingual model, for example intfloat/multilingual-e5-small
--
-- Hybrid query (:text is the search text, :embedding its vector from the same model):
--
--   with q as (
--     select lahja.to_query(:text) as tq, :embedding::extensions.vector as emb
--   ),
--   keyword as (
--     select p.id, row_number() over (order by lahja.rank(p.search, q.tq) desc) as r
--     from products p, q
--     where p.search @@ q.tq
--     order by r
--     limit 50
--   ),
--   semantic as (
--     select p.id, row_number() over (order by p.embedding operator(extensions.<=>) q.emb) as r
--     from products p, q
--     order by r
--     limit 50
--   )
--   select coalesce(k.id, s.id) as id, lahja.rrf_score(k.r, s.r) as score
--   from keyword k
--   full join semantic s on s.id = k.id
--   order by score desc
--   limit 20;
--
-- Requires 001. Safe to run again.

-- RRF score for one item. A rank is 1 for the best result; null means the item
-- is not in that list. k = 60 is the usual default: larger k flattens the
-- difference between top ranks. Weights let you trust one list more.
create or replace function lahja.rrf_score(
  keyword_rank   bigint,
  vector_rank    bigint,
  k              int    default 60,
  keyword_weight float8 default 1.0,
  vector_weight  float8 default 1.0
)
returns float8
language sql
immutable
parallel safe
as $$
  select coalesce(keyword_weight / (k + keyword_rank), 0)
       + coalesce(vector_weight / (k + vector_rank), 0)
$$;

comment on function lahja.rrf_score(bigint, bigint, int, float8, float8) is
  'Reciprocal Rank Fusion score from a keyword rank and a vector rank (null = not found).';

-- ===== extension only =====

-- Back up user lexicon rows only; starter rows are recreated by this script.
select pg_catalog.pg_extension_config_dump('lahja.lexicon', 'where not is_starter');
